struct Chat
{
    string nom;
    int age;
};

int trouverPlusVieux(const vector<Chat>& chats)
{
    int indiceMax = 0;
    for (size_t i = 1; i < chats.size(); ++i)
    {
        if (chats[i].age > chats[indiceMax].age)
        {
            indiceMax = i;
        }
    }
    return indiceMax;
}

int main()
{
    vector<Chat> refuge = { { "Mimi", 3 }, { "Tigrou", 10 }, { "Luna", 7 } };
    int i = trouverPlusVieux(refuge);
    cout << refuge[i].nom << '\n';
    return 0;
}

